Algorithm for Paper 2 practice (Python, written for this exercise)

def find_position(items, target):
    low = 0
    high = len(items) - 1
    steps = 0
    while low <= high:
        mid = (low + high) // 2
        steps = steps + 1
        if items[mid] == target:
            return mid, steps
        elif items[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1, steps

